import { useEffect, useId, useRef, useState } from 'react';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import '@kerfjs/ui/layout.css';
import './item-dialog.css';
type Item = { id: string; title: string; summary: string; owner: string; updated: string };
export function ItemDialog({ open, items, onClose, onChoose }: {
  open: boolean; items: Item[]; onClose: () => void; onChoose: (id: string) => void;
}) {
  const ref = useRef<HTMLDialogElement>(null);
  const prefix = useId();
  const [selectedId, select] = useState<string | null>(null);
  const selected = items.find(item => item.id === selectedId) ?? items[0];
  useEffect(() => {
    const dialog = ref.current!;
    const previous = document.activeElement as HTMLElement | null;
    if (open && !dialog.open) dialog.showModal();
    if (!open && dialog.open) dialog.close();
    return () => {
      if (dialog.open) dialog.close();
      if (previous?.isConnected) previous.focus();
    };
  }, [open]);
  return <dialog ref={ref} className="kui-layout item-dialog"
    aria-labelledby={prefix + '-title'} aria-describedby={prefix + '-summary'}
    onCancel={event => { event.preventDefault(); onClose(); }}>
    <div className="item-dialog-frame">
      <header>
        <DialogHeader title={<span id={prefix + '-title'}>Choose an item</span>}
          description={<span id={prefix + '-summary'}>Review the details, then confirm your selection.</span>} />
        <button type="button" onClick={onClose} aria-label="Close item chooser">Close</button>
      </header>
      <div className="kui-dialog-body item-dialog-scroll">
        <div className="item-dialog-columns">
          <fieldset>
            <legend>Items</legend>
            {items.length === 0 && <p>No items available.</p>}
            {items.map(item => <label className="item-choice" key={item.id}>
              <input type="radio" name={prefix + '-items'} value={item.id}
                checked={selected?.id === item.id} onChange={() => select(item.id)} />
              {item.title}
            </label>)}
          </fieldset>
          <section aria-label="Selected item details" aria-live="polite">
            {selected ? <>
              <h2>{selected.title}</h2><p>{selected.summary}</p>
              <dl><dt>Owner</dt><dd>{selected.owner}</dd><dt>Last updated</dt><dd>{selected.updated}</dd></dl>
            </> : <p>Select an item to see its details.</p>}
          </section>
        </div>
      </div>
      <footer className="item-dialog-actions">
        <button type="button" onClick={onClose}>Cancel</button>
        <button type="button" disabled={!selected} onClick={() => selected && onChoose(selected.id)}>Use selected item</button>
      </footer>
    </div>
  </dialog>;
}
// Native modal dialog supplies focus containment and inert background.
// Confirm DialogHeader's public title/description content types at integration.

