.item-dialog { padding: 0; max-inline-size: min(56rem, calc(100vw - 2rem)); max-block-size: calc(100dvh - 2rem); overflow: hidden; }
.item-dialog-frame { display: flex; flex-direction: column; max-block-size: calc(100dvh - 2rem); }
.item-dialog-scroll { overflow: auto; min-block-size: 0; }
.item-dialog-columns { display: grid; grid-template-columns: minmax(12rem, 1fr) minmax(0, 2fr); }
.item-dialog-columns > * { min-inline-size: 0; overflow-wrap: anywhere; }
.item-choice { display: flex; align-items: center; min-block-size: 2.75rem; }
.item-dialog-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; }
.item-dialog :focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
@media (max-width: 40rem) { .item-dialog-columns { grid-template-columns: minmax(0, 1fr); } }
